118	static void policy_uv_async_queue_cb(uv_async_queue_t* asyncq, void* data)
119	{
120	    int cmd = (int)(intptr_t)data;
121	    uvpolicy_priv_s* priv = asyncq->data;
122	
123	    if (cmd == POLICY_UV_ASYNCQ_EXIT_CMD) {
124	        syslog(LOG_INFO, "policy_uv_async_queue_cb recv exit cmd\n");
125	        uv_async_queue_close(&priv->async_queue, policy_uv_async_queue_close_cb);
126	        return;
127	    } else if (priv->async_cb) {
128	        priv->async_cb(asyncq, data);
129	    } else {
130	        syslog(LOG_ERR, "WithOut priv->async_cb !\n");
131	    }
132	}
