176	void policy_uv_get_string_cb(void* cookie, int ret, const char* val)
177	{
178	    char *str = NULL;
179	    uvpolicy_priv_s* priv = (uvpolicy_priv_s*)cookie;
180	    pthread_mutex_lock(priv->mutex);
181	    priv->ret = ret;
182	    str = val ? (char*)val : "none";
183	    priv->str_val = strdup(str);
184	    pthread_cond_signal(priv->cond);
185	    pthread_mutex_unlock(priv->mutex);
186	    syslog(LOG_INFO, "%s: ret = %d, val = %s \n", __func__, priv->ret, priv->str_val);
187	}
