235	static ssize_t media_process_data(void* handle, bool player,
236	    void* data, size_t len)
237	{
238	    MediaIOPriv* priv = handle;
239	    int ret = -EINVAL;
240	
241	    if (!handle || !data || !len)
242	        return ret;
243	
244	    atomic_fetch_add(&priv->refs, 1);
245	
246	    if (priv->socket <= 0)
247	        goto out;
248	
249	    if (player) {
250	        ret = send(priv->socket, data, len, 0);
251	        if (ret == len)
252	            goto out;
253	        else if (ret == 0)
254	            errno = ECONNRESET;
255	        else if (ret < 0 && errno == EINTR) {
256	            ret = -errno;
257	            goto out;
258	        }
259	    } else {
260	        ret = recv(priv->socket, data, len, 0);
261	        if (ret > 0)
262	            goto out;
263	        else if (ret == 0)
264	            errno = ECONNRESET;
265	        else if (ret < 0 && errno == EINTR) {
266	            ret = -errno;
267	            goto out;
268	        }
269	    }
270	
271	    close(priv->socket);
272	    priv->socket = 0;
273	    if (priv->socket_fd > 0)
274	        close(priv->socket_fd);
275	    ret = -errno;
276	
277	out:
278	    media_release_cb(priv);
279	    return ret;
280	}
