134	static void* policy_uvloop_thread(void* cookie)
135	{
136	    int ret;
137	    uvpolicy_priv_s* priv = (uvpolicy_priv_s*)cookie;
138	
139	    priv->async_queue.data = priv;
140	    ret = uv_async_queue_init(priv->loop, &priv->async_queue, policy_uv_async_queue_cb);
141	    if (ret < 0) {
142	        syslog(LOG_INFO, "uv_async_queue_init failed %d\n", ret);
143	        return NULL;
144	    }
145	        
146	    pthread_mutex_lock(priv->mutex);
147	    priv->uv_running = true;
148	    pthread_cond_signal(priv->cond);
149	    pthread_mutex_unlock(priv->mutex);
150	
151	    while (priv->uv_running) {
152	        ret = uv_run(priv->loop, UV_RUN_DEFAULT);
153	        if (ret == 0)
154	            break;
155	    }
156	
157	    pthread_mutex_lock(priv->mutex);
158	    priv->uv_running = false;
159	    pthread_cond_signal(priv->cond);
160	    pthread_mutex_unlock(priv->mutex);
161	    syslog(LOG_INFO, "uvloop stop run:%d\n", ret);
162	
163	    return NULL;
164	}
165	void policy_uv_get_int_cb(void* cookie, int ret, int val)
166	{
167	    uvpolicy_priv_s* priv = (uvpolicy_priv_s*)cookie;
168	    pthread_mutex_lock(priv->mutex);
169	    priv->ret = ret;
170	    priv->int_val = val;
171	    pthread_cond_signal(priv->cond);
172	    pthread_mutex_unlock(priv->mutex);
173	    syslog(LOG_INFO, "%s: ret = %d, val =%d \n", __func__, priv->ret, priv->int_val);
174	}
