189	void policy_uv_common_cb(void* cookie, int ret)
190	{
191	    uvpolicy_priv_s* priv = (uvpolicy_priv_s*)cookie;
192	    pthread_mutex_lock(priv->mutex);
193	    priv->ret = ret;
194	    pthread_cond_signal(priv->cond);
195	    pthread_mutex_unlock(priv->mutex);
196	    syslog(LOG_INFO, "%s: ret = %d\n", __func__, priv->ret);
197	}
